+/**
+ * Variance per item for sales sold between two days (inclusive): theoretical
+ * use from the recipes, actual use from every consume movement, and
+ * difference = actual - theoretical. Items where either is above zero.
+ */
+export function varianceReport(store, from, to) {
+  const rows = new Map();
+  const row = (itemId) => {
+    if (!rows.has(itemId)) rows.set(itemId, { itemId, theoretical: 0, actual: 0 });
+    return rows.get(itemId);
+  };
+  for (const s of store.data.sales ?? []) {
+    const day = s.soldAt.slice(0, 10);
+    if (day < from || day > to) continue;
+    for (const n of scaled(getRecipe(store, getDish(store, s.dishId).recipeId), s.qty)) row(n.itemId).theoretical += n.qty;
+  }
+  for (const m of store.data.movements) {
+    if (m.type !== "consume") continue;
+    const day = m.at.slice(0, 10);
+    if (day < from || day > to) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (batch) row(batch.itemId).actual += m.qty;
+  }
+  const r3 = (n) => Math.round(n * 1000) / 1000;
+  return [...rows.values()]
+    .map((r) => ({ itemId: r.itemId, theoretical: r3(r.theoretical), actual: r3(r.actual), difference: r3(r.actual - r.theoretical) }))
+    .filter((r) => r.theoretical > 0 || r.actual > 0)
+    .sort((a, b) => a.itemId - b.itemId);
+}
